+/// Write the report rows as CSV.
+pub fn export_csv(rows: &[Row], out: &mut impl Write) -> io::Result<()> {
+    writeln!(out, "id,name,total")?;
+    for row in rows {
+        let name = row.name.replace(',', " ");
+        writeln!(out, "{},{},{:.2}", row.id, name, row.total)?;
+    }
+    Ok(())
+}

